def peel(paths):
    """Return (rounds, core_paths). rounds maps removed canonical edge -> round."""
    current = dict(paths)
    rounds = {}
    rnd = 1
    while True:
        stats = {}
        for p in current:
            first = p[0]
            last = p[-1]
            prev = p[0]
            for cur in p[1:]:
                e = canonical(prev, cur)
                rec = stats.get(e)
                if rec is None:
                    rec = [True, True]
                    stats[e] = rec
                u, v = e
                if first != u and last != u:
                    rec[0] = False
                if first != v and last != v:
                    rec[1] = False
                prev = cur
        marked = {e for e, ok in stats.items() if ok[0] or ok[1]}
        if not marked:
            break
        for e in marked:
            if e not in rounds:
                rounds[e] = rnd
        new_current = {}
        for p, cnt in current.items():
            fm = canonical(p[0], p[1]) in marked
            lm = canonical(p[-2], p[-1]) in marked
            start = 1 if fm else 0
            stop = len(p) - (1 if lm else 0)
            np = p[start:stop]
            if len(np) >= 2:
                new_current[np] = new_current.get(np, 0) + cnt
        current = new_current
        rnd += 1

    core_edges = set()
    for p in current:
        prev = p[0]
        for cur in p[1:]:
            core_edges.add(canonical(prev, cur))
            prev = cur
    return rounds, current, core_edges


def validate_order_and_width(order, core_links, scopes):
    m = len(core_links)
    if len(order) != m:
        raise Invalid()
    index = {e: i for i, e in enumerate(core_links)}
    seen = set()
    pos_of_var = [0] * m
    for pos, e in enumerate(order):
        if e not in index:
            raise Invalid()
        if e in seen:
            raise Invalid()
        seen.add(e)
        pos_of_var[index[e]] = pos
    if len(seen) != m:
        raise Invalid()

    # Primal graph: every phi scope is a clique.
    adj = [set() for _ in range(m)]
    for scope in scopes:
        xs = list(scope)
        for i in range(len(xs)):
            a = xs[i]
            for j in range(i + 1, len(xs)):
                b = xs[j]
                adj[a].add(b)
                adj[b].add(a)

    for pos, e in enumerate(order):
        x = index[e]
        neigh = list(adj[x])
        if len(neigh) > 4:
            raise Invalid()
        for i in range(len(neigh)):
            a = neigh[i]
            for j in range(i + 1, len(neigh)):
                b = neigh[j]
                adj[a].add(b)
                adj[b].add(a)
        for y in neigh:
            adj[y].discard(x)
        adj[x].clear()
    return pos_of_var


def build_scopes_and_occurrences(core_paths, edge_index):
    m = len(edge_index)
    scopes = [{i} for i in range(m)]
    occurrences = []

    def ctx_spec(w, dest):
        f = canonical(w, dest)
        fi = edge_index.get(f)
        if fi is None:
            raise Invalid()
        return (fi, w > dest)

    for p, cnt in core_paths.items():
        plen = len(p)
        for i in range(plen - 1):
            a = p[i]
            b = p[i + 1]
            center = edge_index[canonical(a, b)]
            if a < b:
                # The occurrence already runs in canonical direction.
                if i == 0:
                    left = 0
                else:
                    left = ctx_spec(p[i - 1], a)
                if i + 2 >= plen:
                    right = 2
                else:
                    right = ctx_spec(b, p[i + 2])
            else:
                # Reverse the whole path; the occurrence is then b -> a.
                if i + 2 >= plen:
                    left = 0
                else:
                    left = ctx_spec(p[i + 2], b)
                if i == 0:
                    right = 2
                else:
                    right = ctx_spec(a, p[i - 1])
            occurrences.append((center, left, right, cnt))
            s = scopes[center]
            if type(left) is tuple:
                s.add(left[0])
            if type(right) is tuple:
                s.add(right[0])
    return scopes, occurrences


def make_factors(m, scopes, occurrences):
    groups = [dict() for _ in range(m)]
    for center, left, right, cnt in occurrences:
        d = groups[center]
        key = (left, right)
        d[key] = d.get(key, 0) + cnt

    factors = []
    for center in range(m):
        others = sorted(scopes[center] - {center})
        # Put the center in the first (most significant) slot.
        vars = (center,) + tuple(others)
        k = len(vars)
        tail = 3 ** (k - 1)
        vals = [0] * (3 ** k)
        posmap = {v: j for j, v in enumerate(vars)}
        combos = list(product(range(3), repeat=k - 1))
        for (left, right), cnt in groups[center].items():
            for ci, cstates in enumerate(combos):
                if type(left) is int:
                    ls = left
                else:
                    st = cstates[posmap[left[0]] - 1]
                    ls = 2 - st if left[1] else st
                if type(right) is int:
                    rs = right
                else:
                    st = cstates[posmap[right[0]] - 1]
                    rs = 2 - st if right[1] else st
                target = G[ls][rs]
                vals[target * tail + ci] += cnt
        factors.append((vars, vals))
    return factors


def run_ve(factors, m, pos_of_var, evidence=None):
    """Exact sum of product. evidence is (var_index, state) or None."""
    buckets = [[] for _ in range(m)]
    constant = 1

    def add_factor(fvars, vals):
        p = min(pos_of_var[v] for v in fvars)
        buckets[p].append((fvars, vals))

    for fvars, vals in factors:
        add_factor(fvars, vals)
    if evidence is not None:
        evar, estate = evidence
        ev = [0, 0, 0]
        ev[estate] = 1
        add_factor((evar,), ev)

    for p in range(m):
        selected = buckets[p]
        if not selected:
            # An unconstrained ternary variable contributes a factor of 3.
            constant *= 3
            continue
        union_set = set()
        for fvars, vals in selected:
            union_set.update(fvars)
        union = sorted(union_set, key=lambda x: pos_of_var[x])
        k = len(union)
        rem_size = 3 ** (k - 1)
        upos = {v: j for j, v in enumerate(union)}
        prepared = []
        for fvars, vals in selected:
            prepared.append((tuple(upos[v] for v in fvars), vals))

        msg = [0] * rem_size
        total_assignments = 3 ** k
        for flat in range(total_assignments):
            q = flat
            states = [0] * k
            for j in range(k - 1, -1, -1):
                states[j] = q % 3
                q //= 3
            prod = 1
            for positions, vals in prepared:
                fi = 0
                for pos in positions:
                    fi = fi * 3 + states[pos]
                prod *= vals[fi]
                if prod == 0:
                    break
            msg[flat % rem_size] += prod

        buckets[p] = []
        if k == 1:
            constant *= msg[0]
        else:
            rem = union[1:]
            nxt = min(pos_of_var[v] for v in rem)
            buckets[nxt].append((tuple(rem), msg))
    return constant


